def check(candidate):

    def factorize_and_count(n):
        factors = []
        i = 2
        while i * i <= abs(n):
            if n % i:
                i += 1
            else:
                count = 0
                while n % i == 0:
                    n //= i
                    count += 1
                factors.append((i, -count))
        if n != 1:
            factors.append((-n, 1))
        return factors
    assert candidate(8) == [(2, 3)], 'Test case 1 failed'
    assert candidate(24) == [(2, 2), (3, 1)], 'Test case 2 failed'
    assert candidate(-24) == [(-2, 2), (-3, 1)], '-24 should have positive factors'
    assert candidate(1) == [], 'Single digit primes should return empty list'
    assert candidate(0) == [], 'Zero should return empty list'
    return factorize_and_count
